//! 📦️ Sparse collection staging never clones an existing row or document snapshot.
use super::{keyed_plan::{KeyedPlan,PlanAdvance},borrowed_lists::{BorrowedRows,BorrowedDelta,BorrowedKey},list_move::{TypedListMove,OwnedInsertion}};
use semio_framework_os_kernel::{ApplyCapability,RetainedFieldPreparation};
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retirement::RetireOwned,retained_clone::{RetainedClone,RetainedCloneRef,RetainedCloneClose,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep}};
use std::mem::{size_of,ManuallyDrop};
/// 📤 A real sparse delta transfers its already-admitted insertion vector once.
pub trait OwnedDelta<R>:BorrowedDelta<R>+RetainedClone{type Insertion:OwnedInsertion<R>;fn insertion_rows(&mut self)->&mut Vec<Self::Insertion>;}
/// 🧳 The original sparse payload, source lease, rows and numeric plans retain explicit custody.
pub struct RetainedCollection<R:RetireOwned+BorrowedKey,D:OwnedDelta<R>>{plan:KeyedPlan,field:RetainedFieldPreparation<D>,staged:ManuallyDrop<Option<D>>,authored:ManuallyDrop<Option<Vec<D::Insertion>>>,rows:TypedListMove<R,D::Insertion>,retirement:RetainedCloneClose,phase:u8,closing:bool}
impl<R:RetireOwned+BorrowedKey,D:OwnedDelta<R>> Default for RetainedCollection<R,D>{fn default()->Self{Self::new()}}
impl<R:RetireOwned+BorrowedKey,D:OwnedDelta<R>> RetainedCollection<R,D>{
 pub fn new()->Self{Self{plan:KeyedPlan::new(),field:Default::default(),staged:ManuallyDrop::new(None),authored:ManuallyDrop::new(None),rows:TypedListMove::new(),retirement:Default::default(),phase:0,closing:false}}
 fn fault(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
 fn fixed()->RetirementDemand{RetirementDemand{copy_bytes:128,depth:1,..Default::default()}}
 fn nested(mut d:RetirementDemand)->RetirementDemand{d.copy_bytes+=128;d.depth+=1;d}
 fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-128,maximum_depth:g.maximum_depth-1,..g}}
 fn receipt(mut p:RetainedCloneProgress)->RetainedCloneProgress{p.copied_bytes+=128;p.copied_items=p.copied_items.max(1);p}
 fn refused(error:ValueError)->ValueError{let p=Self::receipt(error.retained_progress());error.with_retained_progress(p)}
 pub fn preflight_demand(&self,source:RetainedCloneRef<'_,D>,post:&[R],body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.phase>5{return Err(Self::fault("sparse collection preflight is settled"))}match self.phase{0=>self.plan.demand(&BorrowedRows{held:post,delta:source.get()}).map(Self::nested),1=>self.field.demand(source,body.saturating_sub(128)).map(Self::nested),2=>self.field.exchange_demand().map(Self::nested),3=>self.field.close_demand(body.saturating_sub(128)).map(Self::nested),4=>self.rows.reserve_demand(post.len(),source.get().inserted_len(),self.plan.origins().expect("admitted numeric list").len()).map(Self::nested),5=>Ok(Self::fixed()),_=>unreachable!()}}
 pub fn preflight(&mut self,source:RetainedCloneRef<'_,D>,post:&[R],body:usize,g:RetainedCloneGrant)->Result<PlanAdvance,ValueError>{let d=self.preflight_demand(source,post,body)?;let mut result=PlanAdvance{progress:Default::default(),done:false,error:None};if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,d){return Ok(result)}match self.phase{
  0=>{let step=self.plan.advance(&BorrowedRows{held:post,delta:source.get()},Self::child(g)).map_err(Self::refused)?;result.progress=Self::receipt(step.progress);result.error=step.error;if step.done{self.phase=1}},
  1=>{if self.field.value().is_some(){self.phase=2;result.progress=RetainedCloneProgress{copied_items:1,copied_bytes:128,..Default::default()}}else{result.progress=Self::receipt(self.field.advance(source,body.saturating_sub(128),Self::child(g)).map_err(Self::refused)?.progress())}},
  2=>{let(value,p)=self.field.take(Self::child(g)).map_err(Self::refused)?;*self.staged=value;result.progress=Self::receipt(p);self.field.begin_close();self.phase=3},
  3=>{result.progress=Self::receipt(self.field.close_step(Self::child(g)).map_err(Self::refused)?.progress());if self.field.terminal_is_empty(){self.phase=4}},
  4=>{result.progress=Self::receipt(self.rows.reserve(post.len(),source.get().inserted_len(),self.plan.origins().expect("admitted output coordinates").len(),Self::child(g)).map_err(Self::refused)?.progress());self.phase=5;result.done=true},
  5=>{result.progress=RetainedCloneProgress{copied_items:1,copied_bytes:128,..Default::default()};result.done=true},_=>unreachable!()
 }Ok(result)}
 pub fn membership_commit_demand(&self)->Result<RetirementDemand,ValueError>{if self.closing||self.phase<5{return Err(Self::fault("sparse collection commit lacks read-only admission"))}if self.phase==5{Ok(RetirementDemand{copy_bytes:size_of::<Option<Vec<D::Insertion>>>()*2+size_of::<Vec<D::Insertion>>>()*2+128,depth:1,..Default::default()})}else{self.rows.commit_demand().map(Self::nested)}}
 pub fn commit_membership(&mut self,post:&mut Vec<R>,g:RetainedCloneGrant,capability:ApplyCapability)->Result<RetainedCloneStep,ValueError>{let d=self.membership_commit_demand()?;if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if self.phase==5{*self.authored=Some(std::mem::take(self.staged.as_mut().expect("admitted authored sparse delta").insertion_rows()));self.phase=6;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}if self.phase==6{let step=self.rows.capture(post,&mut self.authored,Self::child(g),capability).map_err(Self::refused)?;self.phase=7;return Ok(RetainedCloneStep::Progress(Self::receipt(step.progress())))}let step=self.rows.advance(post,self.plan.origins().expect("admitted sparse origins"),Self::child(g),capability).map_err(Self::refused)?;if matches!(step,RetainedCloneStep::Complete(_)){self.phase=8;Ok(RetainedCloneStep::Complete(Self::receipt(step.progress())))}else{Ok(RetainedCloneStep::Progress(Self::receipt(step.progress())))}}
 pub fn origins(&self)->Option<&[Option<super::keyed_plan::Origin>]>{self.plan.origins()}
 pub fn modification_targets(&self)->Option<&[usize]>{self.plan.modification_targets()}
 pub fn staged(&self)->Option<&D>{self.staged.as_ref()}
 pub fn staged_mut(&mut self,_capability:ApplyCapability)->Result<&mut D,ValueError>{if self.phase<5||self.phase>8||self.closing{return Err(Self::fault("sparse patch access requires membership commit"))}Ok(self.staged.as_mut().expect("original authored sparse owner"))}
 pub fn begin_close(&mut self){self.closing=true;self.field.begin_close();self.rows.begin_close();self.plan.begin_close()}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.field.terminal_is_empty(){return self.field.close_demand(body)}if !self.rows.terminal_is_empty(){return self.rows.close_demand(body)}if !self.retirement.is_empty(){return self.retirement.next_owner_demands::<D>(false,&None,body)}if self.staged.is_some(){return self.retirement.next_owner_demands::<D>(true,&None,body)}if self.authored.is_some(){return self.retirement.next_owner_demands::<Vec<D::Insertion>>(true,&None,body)}if !self.plan.terminal_is_empty(){return Ok(self.plan.close_demand())}Ok(Default::default())}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(Self::fault("sparse collection original close not begun"))}let d=self.close_demand(g.maximum_copy_bytes)?;if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.field.terminal_is_empty(){return self.field.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()))}if !self.rows.terminal_is_empty(){return self.rows.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()))}if !self.retirement.is_empty(){return self.retirement.step_granted(g).map(|s|RetainedCloneStep::Progress(s.progress()))}if let Some(step)=self.retirement.begin_granted(&mut self.staged,g)?{return Ok(RetainedCloneStep::Progress(step.progress()))}if let Some(step)=self.retirement.begin_granted(&mut self.authored,g)?{return Ok(RetainedCloneStep::Progress(step.progress()))}if !self.plan.terminal_is_empty(){return self.plan.close_step(g).map(RetainedCloneStep::Progress)}Ok(RetainedCloneStep::Complete(Default::default()))}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.field.terminal_is_empty()&&self.rows.terminal_is_empty()&&self.staged.is_none()&&self.authored.is_none()&&self.retirement.is_empty()&&self.plan.terminal_is_empty()}
}
impl<R:RetireOwned+BorrowedKey,D:OwnedDelta<R>> Drop for RetainedCollection<R,D>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original sparse collection ownership needs funded close")}}

